# ============================================================

missingness_records = []


for feature in final_df.columns:

    missing_count = int(
        final_df[feature].isna().sum()
    )

    missing_percentage = (
        missing_count
        / len(final_df)
        * 100
    )

    missingness_records.append(
        {
            "Feature": feature,
            "Missing_Count": missing_count,
            "Missing_Percentage": round(
                missing_percentage,
                4
            )
        }
    )


missingness_df = pd.DataFrame(
    missingness_records
)


