def manifest_truthy(value):
    """Interpret the boolean encodings used by the Part 13 manifest."""
    if isinstance(value, bool):
        return value
    if pd.isna(value):
        return False
    return str(value).strip().lower() in {"true", "1", "yes", "y", "t"}


